import sys


def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    G = []
    idx = 2
    for i in range(N):
        row = [int(x) for x in input_data[idx : idx + M]]
        idx += M
        G.append(row)

    # Opção 0: (i + j) % 2 == 0 tem paridade ÍMPAR (1), e (i + j) % 2 == 1 tem paridade PAR (0)
    # Opção 1: (i + j) % 2 == 0 tem paridade PAR (0), e (i + j) % 2 == 1 tem paridade ÍMPAR (1)

    cost0 = 0
    cost1 = 0

    for i in range(N):
        for j in range(M):
            p = G[i][j] % 2
            # Para opção 0: paridade desejada é 1 se (i+j)%2 == 0 senão 0
            target0 = 1 if (i + j) % 2 == 0 else 0
            if p != target0:
                cost0 += 1

            # Para opção 1: paridade desejada é 0 se (i+j)%2 == 0 senão 1
            target1 = 0 if (i + j) % 2 == 0 else 1
            if p != target1:
                cost1 += 1

    if cost0 <= cost1:
        min_cost = cost0
        best_option = 0
    else:
        min_cost = cost1
        best_option = 1

    ans_matrix = []
    for i in range(N):
        row = []
        for j in range(M):
            val = G[i][j]
            p = val % 2
            if best_option == 0:
                target = 1 if (i + j) % 2 == 0 else 0
            else:
                target = 0 if (i + j) % 2 == 0 else 1

            if p != target:
                row.append(val + 1)
            else:
                row.append(val)
        ans_matrix.append(row)

    out = [str(min_cost)]
    for row in ans_matrix:
        out.append(" ".join(map(str, row)))

    print("\n".join(out))


if __name__ == "__main__":
    solve()
